            "title": "Example API",
            "version": "1.0.0",
        },
        "paths": {
            "/users/{user_id}": {
                "get": {
                    "summary": "Get user by ID",
                    "operationId": "get_user",
                    "parameters": [
                        {
                            "name": "user_id",
                            "in": "path",
                            "required": True,
                            "schema": {"type": "string"},
                        }
