                                "application/json": {
                                    "schema": {
                                        "type": "object",
                                        "properties": {
                                            "id": {"type": "string"},
                                            "name": {"type": "string"},
                                        },
                                    }
                                }
                            },
                        }
                    },
                }
            },
            "/posts": {
                "post": {
                    "summary": "Create a post",
                    "operationId": "create_post",
                    "requestBody": {
                        "required": True,
                        "content": {
                            "application/json": {
                                "schema": {
                                    "type": "object",
                                    "properties": {
                                        "title": {"type": "string"},
                                        "content": {"type": "string"},
                                    },
                                    "required": ["title", "content"],
                                }
                            }
                        },
                    },
                    "responses": {
                        "201": {
                            "description": "Post created",
                            "content": {
                                "application/json": {
                                    "schema": {
                                        "type": "object",
                                        "properties": {
                                            "id": {"type": "string"},
                                            "title": {"type": "string"},
                                        },
                                    }
                                }
                            },
                        }
                    },
                }
            },
        },
    }

    client = httpx.AsyncClient(base_url="https://api.example.com")

    mcp = await create_openapi_mcp_server(
        openapi_spec=spec,
        client=client,
        server_name="Example OpenAPI Server",
    )

    print("MCP Server created with tools:")
    for tool in mcp.list_tools():
        print(f"  - {tool.name}: {tool.description}")

    try:
        await mcp.run_stdio_async()
    finally:
        await client.aclose()


if __name__ == "__main__":
    asyncio.run(main())

